<?php
session_start();
if (!isset($_SESSION['user_id'])) { header('Location: ../../login.php'); exit; }
$files = [    'modules/locations/action.php' => base64_decode(''),
    'modules/stock/list.php' => base64_decode(''),
    'modules/stock/move.php' => base64_decode(''),
    'modules/stock/action.php' => base64_decode(''),
    'modules/stock/ledger.php' => base64_decode(''),
];
$written = 0; $failed = 0;
foreach ($files as $path => $content) {
    $full = __DIR__ . '/' . $path;
    $dir = dirname($full);
    if (!is_dir($dir)) mkdir($dir, 0755, true);
    if (file_put_contents($full, $content) !== false) {
        echo "OK: $path<br>\n"; $written++;
    } else {
        echo "FAIL: $path<br>\n"; $failed++;
    }
}
echo "<br>Done: $written written, $failed failed\n";